ST.html:p:
IF fire AND NOT edge_ir THEN
    IF pos_target > 100 OR pos_target < 0 THEN
        Done := TRUE;
    ELSE
        tgt := INT_TO_REAL(pos_target);
        Busy := TRUE; Done := FALSE; Aborted := FALSE;
    END_IF;
ELSIF fire AND NOT Busy AND (ABS(INT_TO_REAL(pos_target) - tgt) > 0.499) THEN
    tgt := INT_TO_REAL(pos_target);
    Busy := TRUE; Done := FALSE; Aborted := FALSE;
END_IF;
edge_ir := fire;

IF hold_req THEN
    IF vel > 0.0 THEN vel := MAX(0.0, vel - dec_req * SCAN_T);
    ELSIF vel < 0.0 THEN vel := MIN(0.0, vel + dec_req * SCAN_T);
    END_IF;
    IF vel = 0.0 AND Busy THEN
        Busy := FALSE; Done := FALSE; Aborted := TRUE;
    END_IF;
ELSIF Busy THEN
    dist := tgt - pos;
    stop_d := (vel * vel) / (2.0 * dec_req);
    IF ABS(dist) <= stop_d THEN
        IF dist >= 0.0 THEN vel := MAX(0.0, vel - dec_req * SCAN_T);
        ELSE vel := MIN(0.0, vel + dec_req * SCAN_T);
        END_IF;
        IF vel = 0.0 AND ABS(dist) <= POSWIN THEN
            pos := tgt; Busy := FALSE; Done := TRUE; Aborted := FALSE;
        END_IF;
    ELSE
        IF dist > 0.0 THEN vel := MIN(vel_req, vel + acc_req * SCAN_T);
        ELSE vel := MAX(-vel_req, vel - acc_req * SCAN_T);
        END_IF;
    END_IF;
END_IF;

pos := pos + vel * SCAN_T;
Setpoint := REAL_TO_INT(pos);

IF fire AND NOT edge_irz THEN
    IF pos_target > 100 OR pos_target < 0 THEN
        Done := TRUE;
    ELSE
        tgt := INT_TO_REAL(pos_target);
        Busy := TRUE; Done := FALSE; Aborted := FALSE;
    END_IF;
ELSIF fire AND NOT Busy AND (ABS(INT_TO_REAL(pos_target) - tgt) > 0.499) THEN
    tgt := INT_TO_REAL(pos_target);
    Busy := TRUE; Done := FALSE; Aborted := FALSE;
END_IF;
edge_irz := fire;

IF hold_req THEN
    IF vel > 0.0 THEN vel := MAX(0.0, vel - dec_req * SCAN_T);
    ELSIF vel < 0.0 THEN vel := MIN(0.0, vel + dec_req * SCAN_T);
    END_IF;
    IF vel = 0.0 AND Busy THEN
        Busy := FALSE; Done := FALSE; Aborted := TRUE;
    END_IF;
ELSIF Busy THEN
    dist := tgt - pos;
    stop_d := (vel * vel) / (2.0 * dec_req);
    IF ABS(dist) <= stop_d THEN
        IF dist >= 0.0 THEN vel := MAX(0.0, vel - dec_req * SCAN_T);
        ELSE vel := MIN(0.0, vel + dec_req * SCAN_T);
        END_IF;
        IF vel = 0.0 AND ABS(dist) <= POSWIN THEN
            pos := tgt; Busy := FALSE; Done := TRUE; Aborted := FALSE;
        END_IF;
    ELSE
        IF dist > 0.0 THEN vel := MIN(vel_req, vel + acc_req * SCAN_T);
        ELSE vel := MAX(-vel_req, vel - acc_req * SCAN_T);
        END_IF;
    END_IF;
END_IF;

pos := pos + vel * SCAN_T;
Setpoint := REAL_TO_INT(pos);

cmd := cw AND 16#000F;

IF state = 7 AND (cw AND 16#0080) <> 0 THEN
    state := 1;
END_IF;

CASE state OF
    1: IF cmd = 16#06 THEN state := 2; END_IF;
    2: IF cmd = 16#07 THEN state := 3;
       ELSIF cmd = 16#0F THEN state := 4;
       ELSIF cmd = 16#00 THEN state := 1;
       END_IF;
    3: IF cmd = 16#0F THEN state := 4;
       ELSIF cmd = 16#06 THEN state := 2;
       ELSIF cmd = 16#00 THEN state := 1;
       ELSIF cmd = 16#02 THEN state := 5;
       END_IF;
    4: IF cmd = 16#07 THEN state := 3;
       ELSIF cmd = 16#06 THEN state := 2;
       ELSIF cmd = 16#00 THEN state := 1;
       ELSIF cmd = 16#02 THEN state := 5;
       END_IF;
    5: IF v_out = 0.0 THEN
           IF cmd = 16#0F THEN state := 4;
           ELSIF cmd = 16#06 THEN state := 2;
           ELSIF cmd = 16#00 THEN state := 1;
           END_IF;
       END_IF;
    6: IF v_out = 0.0 THEN state := 7; END_IF;
END_CASE;

IF state >= 4 AND state <= 6 THEN
    v_ff := INT_TO_REAL(Setpoint - sp_prev) / SCAN_T;
    pos_err := INT_TO_REAL(Setpoint) - INT_TO_REAL(pos_fb);
    v_out := v_ff + KP * pos_err;
    IF v_out > 120.0 THEN v_out := 120.0; END_IF;
    IF v_out < -120.0 THEN v_out := -120.0; END_IF;
    IF v_ff = 0.0 AND ABS(pos_err) <= 1.5 THEN
        v_out := 0.0;
    END_IF;
ELSIF state = 5 THEN
    IF v_out > 0.0 THEN v_out := MAX(0.0, v_out - QS_DECEL * SCAN_T);
    ELSIF v_out < 0.0 THEN v_out := MIN(0.0, v_out + QS_DECEL * SCAN_T);
    END_IF;
ELSE
    v_out := 0.0;
END_IF;

sp_prev := Setpoint;
v_cmd := REAL_TO_INT(v_out);

sw := 0;
CASE state OF
    1: sw := 16#0040;
    2: sw := 16#0031;
    3: sw := 16#0033;
    4: sw := 16#0037;
    5: sw := 16#0014;
    7: sw := 16#0018;
END_CASE;
IF state = 4 THEN
    IF ABS(pos_err) <= 2.0 AND v_ff = 0.0 THEN
        sw := sw OR 16#0400;
    END_IF;
END_IF;

IF Enable AND (EnablePositive OR EnableNegative) AND pstep = 4 AND (sw AND 16#0004) = 0 AND (sw AND 16#0008) = 0 THEN
    pstep := 0;
END_IF;
IF Enable AND (EnablePositive OR EnableNegative) THEN
    CASE pstep OF
        0: cw := (cw AND 16#00F0) OR 16#0006;  pstep := 1;
        1: IF (sw AND 16#0001) <> 0 THEN cw := (cw AND 16#00F0) OR 16#0007; pstep := 2; END_IF;
        2: IF (sw AND 16#0002) <> 0 THEN cw := (cw AND 16#00F0) OR 16#000F; pstep := 3; END_IF;
        3: IF (sw AND 16#0004) <> 0 THEN pstep := 4; END_IF;
    END_CASE;
ELSE
    cw := (cw AND 16#00F0) OR 16#0006;
    pstep := 0;
END_IF;
Status := (sw AND 16#0004) <> 0;
Busy := Enable AND pstep < 4;
Error := (sw AND 16#0008) <> 0;

IF fire AND NOT edge_ma THEN
    Error := FALSE; ErrorID := 0; CommandAborted := FALSE;
    IF (sw AND 16#0008) <> 0 THEN
        Error := TRUE; ErrorID := 2;
    ELSIF (sw AND 16#0004) = 0 THEN
        Error := TRUE; ErrorID := 3;
    ELSIF Position < 0 OR Position > 100 THEN
        Error := TRUE; ErrorID := 1;
    ELSE
        interp_exe := TRUE;
        dyn_vel := Velocity; dyn_acc := Acceleration; dyn_dec := Deceleration;
    END_IF;
END_IF;
edge_ma := fire;

IF interp_exe AND abort_bus AND NOT edge_ab THEN
    interp_exe := FALSE;
    CommandAborted := TRUE;
END_IF;
edge_ab := abort_bus;
Busy := interp_exe;
Active := interp_exe;
Done := NOT interp_exe AND NOT Error;

IF fire AND NOT edge_hm THEN
    Error := FALSE;
    IF (sw AND 16#0008) <> 0 THEN
        Error := TRUE;
    ELSIF (sw AND 16#0004) = 0 THEN
        Error := TRUE;
    ELSE
        home_exe := TRUE;
    END_IF;
END_IF;
edge_hm := fire;
Busy := home_exe;
Done := NOT home_exe AND NOT Error;

IF fire AND NOT edge_hl THEN
    done_latch := FALSE;
    Stopping := TRUE;
END_IF;
edge_hl := fire;
IF Stopping AND NOT ax_busy THEN
    Stopping := FALSE;
    done_latch := TRUE;
END_IF;
Busy := Stopping;
Done := done_latch AND NOT Stopping;
Error := FALSE;

IF NOT (JogForward OR JogBackward) THEN
    jog_pos := cur_pos;
END_IF;
IF (sw AND 16#0008) <> 0 OR (sw AND 16#0004) = 0 THEN
    Error := TRUE;
    Busy := FALSE;
ELSE
    Error := FALSE;
    jstep := REAL_TO_INT(Velocity * SCAN_T);
    IF jstep < 1 THEN jstep := 1; END_IF;
    IF JogForward AND NOT JogBackward THEN
        IF jog_pos < 100 THEN jog_pos := jog_pos + jstep; END_IF;
        IF jog_pos > 100 THEN jog_pos := 100; END_IF;
        Busy := TRUE;
    ELSIF JogBackward AND NOT JogForward THEN
        IF jog_pos > 0 THEN jog_pos := jog_pos - jstep; END_IF;
        IF jog_pos < 0 THEN jog_pos := 0; END_IF;
        Busy := TRUE;
    ELSE
        Busy := FALSE;
    END_IF;
END_IF;

Valid := Enable;
Moving := interp_busy OR (v_act <> 0);
ErrorStop := (sw AND 16#0008) <> 0;
Disabled := (sw AND 16#0004) = 0;
StandStill := Enable AND NOT Moving AND NOT ErrorStop AND NOT Disabled;

body.ST:
dbg_0 := pl_step;
dbg_1 := BOOL_TO_INT(seq_fault);
dbg_2 := BOOL_TO_INT(go_x_exe);
dbg_3 := BOOL_TO_INT(go_y_exe);
dbg_4 := BOOL_TO_INT(go_z_exe);
dbg_5 := BOOL_TO_INT(hm_x_exe);

prog_id := 2;

(* ---- 笔态(纯物理判定) 与 急停/故障 ---- *)
pen_down := (z_fb <= 2);
stop_req := quickstop OR seq_fault;
IF cmd_reset AND NOT quickstop THEN
    seq_fault := FALSE;
END_IF;

(* ---- 目标总线默认值 ---- *)
x_tgt := x_sp;  y_tgt := y_sp;  z_tgt := z_sp;

(* ---- 绘图序列目标选择(步表权威) ---- *)
CASE pl_step OF
    0: pl_step := pl_step;
    1: z_tgt := 10;
    2: x_tgt := 20;  y_tgt := 20;
    3: z_tgt := 0;
    4: x_tgt := 80;
    5: y_tgt := 80;
    6: x_tgt := 20;
    7: y_tgt := 20;
    8: z_tgt := 10;
    9: x_tgt := 50;  y_tgt := 50;
END_CASE;

(* ---- 序列启动: C4 使能前提 + 抬笔前提 ---- *)
edge_draw := cmd_draw AND NOT prev_draw;
prev_draw := cmd_draw;
IF pl_step = 0 AND edge_draw AND run AND all_oe AND NOT pen_down
   AND NOT quickstop AND NOT seq_fault THEN
    go_x_exe := TRUE;  go_y_exe := TRUE;  go_z_exe := TRUE;
    manual_gd := FALSE;
    plot_done := FALSE;
    pl_step := 1;
END_IF;

(* ---- 步进: C2 时序(抬笔确认后 XY, XY 到位后落笔) ---- *)
IF pl_step = 1 AND ix_z.Done AND NOT ix_z.Busy AND (z_fb >= 9) THEN
    pl_step := 2;
ELSIF pl_step = 2 AND ix_x.Done AND ix_y.Done AND NOT ix_x.Busy AND NOT ix_y.Busy THEN
    pl_step := 3;
ELSIF pl_step = 3 AND ix_z.Done AND NOT ix_z.Busy AND (z_fb <= 1) THEN
    pl_step := 4;
ELSIF pl_step = 4 AND ix_x.Done AND NOT ix_x.Busy THEN
    pl_step := 5;
ELSIF pl_step = 5 AND ix_y.Done AND NOT ix_y.Busy THEN
    pl_step := 6;
ELSIF pl_step = 6 AND ix_x.Done AND NOT ix_x.Busy THEN
    pl_step := 7;
ELSIF pl_step = 7 AND ix_y.Done AND NOT ix_y.Busy THEN
    pl_step := 8;
ELSIF pl_step = 8 AND ix_z.Done AND NOT ix_z.Busy AND (z_fb >= 9) THEN
    pl_step := 9;
ELSIF pl_step = 9 AND ix_x.Done AND ix_y.Done AND NOT ix_x.Busy AND NOT ix_y.Busy THEN
    plot_done := TRUE;
    go_x_exe := FALSE;  go_y_exe := FALSE;  go_z_exe := FALSE;
    pl_step := 0;
END_IF;

(* ---- C3 急停/故障中止: 电平中止, 释放+重新使能后可直接重启 ---- *)
IF quickstop OR seq_fault THEN
    pl_step := 0;
    go_x_exe := FALSE;  go_y_exe := FALSE;  go_z_exe := FALSE;
    hm_x_exe := FALSE;  hm_y_exe := FALSE;  hm_z_exe := FALSE;
    manual_gd := FALSE;
    plot_done := FALSE;
END_IF;

(* ---- C6 段超时看门狗: 每段 T#4S (行程/限速+加减速裕量+30%) ---- *)
IF pl_step <> prev_pl THEN
    wd_gate := FALSE;
ELSE
    wd_gate := TRUE;
END_IF;
ton_wd(IN := wd_gate AND (pl_step <> 0), PT := T#4S);
IF ton_wd.Q THEN
    seq_fault := TRUE;
END_IF;
prev_pl := pl_step;

(* ---- 手动通道门控: C1 笔互锁 / C4 使能前提 ---- *)
go_gate := cmd_go AND run AND all_oe AND NOT pen_down AND (pl_step = 0)
           AND NOT quickstop AND NOT seq_fault AND NOT hm_x_exe;
jg_f_gate := jog_fwd AND run AND all_oe AND NOT pen_down AND (pl_step = 0)
             AND NOT quickstop AND NOT seq_fault AND NOT go_x_exe;
jg_r_gate := jog_rev AND run AND all_oe AND NOT pen_down AND (pl_step = 0)
             AND NOT quickstop AND NOT seq_fault AND NOT go_x_exe;

edge_go := go_gate AND NOT prev_go;
prev_go := go_gate;
IF edge_go THEN manual_gd := TRUE; END_IF;

(* ---- X 轴实例组 ---- *)
pwr_x(Enable := run AND NOT seq_fault, EnablePositive := TRUE, EnableNegative := TRUE, cw := x_cw, sw := x_swl);
rap_x(Enable := TRUE, ActualPosition := x_fb);
go_x(fire := go_gate, Position := x_sp, Velocity := 40.0, Acceleration := 80.0, Deceleration := 80.0,
     sw := x_swl, abort_bus := ix_x.Aborted,
     interp_exe := go_x_exe, dyn_vel := x_vel_bus, dyn_acc := x_acc_bus, dyn_dec := x_dec_bus);
hm_x(fire := cmd_home AND run AND all_oe AND NOT quickstop AND NOT seq_fault AND (pl_step = 0),
     sw := x_swl, home_exe := hm_x_exe);
jg_x(JogForward := jg_f_gate, JogBackward := jg_r_gate, Velocity := 40.0,
     cur_pos := x_fb, sw := x_swl, jog_pos := x_jog_pos);
hlt_x(fire := stop_req, ax_busy := ix_x.Busy);
IF hm_x_exe THEN x_tgt := 0; END_IF;
IF jg_x.Busy THEN x_tgt := x_jog_pos; END_IF;
ix_x(fire := go_x_exe OR hm_x_exe OR jg_x.Busy, pos_target := x_tgt,
     hold_req := hlt_x.Stopping, vel_req := x_vel_bus, acc_req := x_acc_bus, dec_req := x_dec_bus);
dv_x(cw := x_cw, Setpoint := x_interp, pos_fb := x_fb);
x_interp := ix_x.Setpoint;
x_sw := WORD_TO_INT(x_swl);
x_v := dv_x.v_cmd;
rds_x(Enable := TRUE, sw := x_swl, interp_busy := ix_x.Busy, v_act := x_v);
IF ix_x.Aborted THEN go_x_exe := FALSE; hm_x_exe := FALSE; END_IF;
IF hm_x_exe AND ix_x.Done AND NOT ix_x.Busy THEN hm_x_exe := FALSE; END_IF;
IF (pl_step = 0) AND go_x_exe AND ix_x.Done AND NOT ix_x.Busy AND NOT go_gate AND NOT jg_x.Busy THEN go_x_exe := FALSE; END_IF;

(* ---- Y 轴实例组 ---- *)
pwr_y(Enable := run AND NOT seq_fault, EnablePositive := TRUE, EnableNegative := TRUE, cw := y_cw, sw := y_swl);
rap_y(Enable := TRUE, ActualPosition := y_fb);
go_y(fire := go_gate, Position := y_sp, Velocity := 40.0, Acceleration := 80.0, Deceleration := 80.0,
     sw := y_swl, abort_bus := ix_y.Aborted,
     interp_exe := go_y_exe, dyn_vel := y_vel_bus, dyn_acc := y_acc_bus, dyn_dec := y_dec_bus);
hm_y(fire := cmd_home AND run AND all_oe AND NOT quickstop AND NOT seq_fault AND (pl_step = 0),
     sw := y_swl, home_exe := hm_y_exe);
hlt_y(fire := stop_req, ax_busy := ix_y.Busy);
IF hm_y_exe THEN y_tgt := 0; END_IF;
ix_y(fire := go_y_exe OR hm_y_exe, pos_target := y_tgt,
     hold_req := hlt_y.Stopping, vel_req := y_vel_bus, acc_req := y_acc_bus, dec_req := y_dec_bus);
dv_y(cw := y_cw, Setpoint := y_interp, pos_fb := y_fb);
y_interp := ix_y.Setpoint;
y_sw := WORD_TO_INT(y_swl);
y_v := dv_y.v_cmd;
rds_y(Enable := TRUE, sw := y_swl, interp_busy := ix_y.Busy, v_act := y_v);
IF ix_y.Aborted THEN go_y_exe := FALSE; hm_y_exe := FALSE; END_IF;
IF hm_y_exe AND ix_y.Done AND NOT ix_y.Busy THEN hm_y_exe := FALSE; END_IF;
IF (pl_step = 0) AND go_y_exe AND ix_y.Done AND NOT ix_y.Busy AND NOT go_gate THEN go_y_exe := FALSE; END_IF;

(* ---- Z 轴实例组 (INTERP_Z: POSWIN=1.0, 动力学 20/60/60) ---- *)
pwr_z(Enable := run AND NOT seq_fault, EnablePositive := TRUE, EnableNegative := TRUE, cw := z_cw, sw := z_swl);
rap_z(Enable := TRUE, ActualPosition := z_fb);
go_z(fire := FALSE, Position := z_sp, Velocity := 20.0, Acceleration := 60.0, Deceleration := 60.0,
     sw := z_swl, abort_bus := ix_z.Aborted,
     interp_exe := go_z_exe, dyn_vel := z_vel_bus, dyn_acc := z_acc_bus, dyn_dec := z_dec_bus);
hm_z(fire := cmd_home AND run AND all_oe AND NOT quickstop AND NOT seq_fault AND (pl_step = 0),
     sw := z_swl, home_exe := hm_z_exe);
hlt_z(fire := stop_req, ax_busy := ix_z.Busy);
IF hm_z_exe THEN z_tgt := 10; END_IF;
ix_z(fire := go_z_exe OR hm_z_exe, pos_target := z_tgt,
     hold_req := hlt_z.Stopping, vel_req := z_vel_bus, acc_req := z_acc_bus, dec_req := z_dec_bus);
dv_z(cw := z_cw, Setpoint := z_interp, pos_fb := z_fb);
z_interp := ix_z.Setpoint;
z_sw := WORD_TO_INT(z_swl);
z_v := dv_z.v_cmd;
rds_z(Enable := TRUE, sw := z_swl, interp_busy := ix_z.Busy, v_act := z_v);
IF ix_z.Aborted THEN go_z_exe := FALSE; hm_z_exe := FALSE; END_IF;
IF hm_z_exe AND ix_z.Done AND NOT ix_z.Busy THEN hm_z_exe := FALSE; END_IF;

(* ---- 输出汇总 ---- *)
all_oe := pwr_x.Status AND pwr_y.Status AND pwr_z.Status;
any_moving := rds_x.Moving OR rds_y.Moving OR rds_z.Moving;
fault_any := seq_fault OR pwr_x.Error OR pwr_y.Error OR pwr_z.Error;
move_done := manual_gd AND (pl_step = 0) AND NOT quickstop AND NOT seq_fault
             AND ix_x.Done AND NOT ix_x.Busy AND ix_y.Done AND NOT ix_y.Busy;
